/** 判语的 B 站回放直链（直达该秒）。 */
export function replayUrl(e: TianjiEntry): string {
	const [h, m, s] = e.t_hms.split(":").map(Number);
	return `https://www.bilibili.com/video/${e.bvid}?p=${e.part}&t=${h * 3600 + m * 60 + s}`;
}

